Here is the commit message:
batman-adv: Avoid double-rtnl_lock ELP metric worker
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

batadv_v_elp_get_throughput() might be called when the RTNL lock is already
held. This could be problematic when the work queue item is cancelled via
cancel_delayed_work_sync() in batadv_v_elp_iface_disable(). In this case,
an rtnl_lock() would cause a deadlock.

To avoid this, rtnl_trylock() was used in this function to skip the
retrieval of the ethtool information in case the RTNL lock was already
held.

But for cfg80211 interfaces, batadv_get_real_netdev() was called - which
also uses rtnl_lock(). The approach for __ethtool_get_link_ksettings() must
also be used instead and the lockless version __batadv_get_real_netdev()
has to be called.

Cc: stable@vger.kernel.org
Fixes: 8c8ecc98f5c6 ("batman-adv: Drop unmanaged ELP metric worker")
Reported-by: Christian Schmidbauer <github@grische.xyz>
Signed-off-by: Sven Eckelmann <sven@narfation.org>
Tested-by: Sören Skaarup <freifunk_nordm4nn@gmx.de>
Signed-off-by: Simon Wunderlich <sw@simonwunderlich.de>

Here is the root cause:
The ELP metric worker function `batadv_v_elp_get_throughput()` calls `batadv_get_real_netdev()`, which acquires the RTNL lock via `rtnl_lock()`. When this worker is cancelled by `cancel_delayed_work_sync()` in `batadv_v_elp_iface_disable()`, the RTNL lock is already held by the cancelling path, leading to a deadlock because the worker waits for the lock, while the canceller waits for the worker to finish.

Here is the patch:
  */
 static bool batadv_v_elp_get_throughput(struct batadv_hardif_neigh_node *neigh,
 					u32 *pthroughput)
 {
 	struct batadv_hard_iface *hard_iface = neigh->if_incoming;
 	struct net_device *mesh_iface = hard_iface->mesh_iface;
 	struct ethtool_link_ksettings link_settings;
 	struct net_device *real_netdev;
 	struct station_info sinfo;
 	u32 throughput;
 	int ret;

 	/* don't query throughput when no longer associated with any
 	 * batman-adv interface
 	 */
 	if (!mesh_iface)
 		return false;

 	/* if the user specified a customised value for this interface, then
 	 * return it directly
 	 */
 	throughput =  atomic_read(&hard_iface->bat_v.throughput_override);
 	if (throughput != 0) {
 		*pthroughput = throughput;
 		return true;
 	}

 	/* if this is a wireless device, then ask its throughput through
 	 * cfg80211 API
 	 */
 	if (batadv_is_wifi_hardif(hard_iface)) {
 		if (!batadv_is_cfg80211_hardif(hard_iface))
 			/* unsupported WiFi driver version */
 			goto default_throughput;

-		real_netdev = batadv_get_real_netdev(hard_iface->net_dev);
+		/* only use rtnl_trylock because the elp worker will be cancelled while
+		 * the rntl_lock is held. the cancel_delayed_work_sync() would otherwise
+		 * wait forever when the elp work_item was started and it is then also
+		 * trying to rtnl_lock
+		 */
+		if (!rtnl_trylock())
+			return false;
+		real_netdev = __batadv_get_real_netdev(hard_iface->net_dev);
+		rtnl_unlock();
 		if (!real_netdev)
 			goto default_throughput;

 		ret = cfg80211_get_station(real_netdev, neigh->addr, &sinfo);

 		if (!ret) {
 			/* free the TID stats immediately */
 			cfg80211_sinfo_release_content(&sinfo);
 		}

 		dev_put(real_netdev);
 		if (ret == -ENOENT) {
 			/* Node is not associated anymore! It would be
 			 * possible to delete this neighbor. For now set
 			 * the throughput metric to 0.
 			 */
 			*pthroughput = 0;
 			return true;
 		}
 		if (ret)
 			goto default_throughput;

 		if (sinfo.filled & BIT(NL80211_STA_INFO_EXPECTED_THROUGHPUT)) {
 			*pthroughput = sinfo.expected_throughput / 100;
 			return true;
 		}

 		/* try to estimate the expected throughput based on reported tx
 		 * rates
 		 */
 		if (sinfo.filled & BIT(NL80211_STA_INFO_TX_BITRATE)) {
 			*pthroughput = cfg80211_calculate_bitrate(&sinfo.txrate) / 3;
 			return true;
 		}

 		goto default_throughput;
 	}

 	/* only use rtnl_trylock because the elp worker will be cancelled while
 	 * the rntl_lock is held. the cancel_delayed_work_sync() would otherwise
 	 * wait forever when the elp work_item was started and it is then also
 	 * trying to rtnl_lock
 	 */
 	if (!rtnl_trylock())
 		return false;

 	/* if not a wifi interface, check if this device provides data via
 	 * ethtool (e.g. an Ethernet adapter)
 	 */
 	ret = __ethtool_get_link_ksettings(hard_iface->net_dev, &link_settings);
 	rtnl_unlock();
 	if (ret == 0) {
 		/* link characteristics might change over time */
 		if (link_settings.base.duplex == DUPLEX_FULL)
 			hard_iface->bat_v.flags |= BATADV_FULL_DUPLEX;
 		else
 			hard_iface->bat_v.flags &= ~BATADV_FULL_DUPLEX;

 		throughput = link_settings.base.speed;
 		if (throughput && throughput != SPEED_UNKNOWN) {
 			*pthroughput = throughput * 10;
 			return true;
 		}
 	}

 default_throughput:
 	if (!(hard_iface->bat_v.flags & BATADV_WARNING_DEFAULT)) {
 		batadv_info(mesh_iface,
 			    "WiFi driver or ethtool info does not provide information about link speeds on interface %s, therefore defaulting to hardcoded throughput values of %u.%1u Mbps. Consider overriding the throughput manually or checking your driver.\n",
 			    hard_iface->net_dev->name,
 			    BATADV_THROUGHPUT_DEFAULT_VALUE / 10,
 			    BATADV_THROUGHPUT_DEFAULT_VALUE % 10);
 		hard_iface->bat_v.flags |= BATADV_WARNING_DEFAULT;
 	}

 	/* if none of the above cases apply, return the base_throughput */
 	*pthroughput = BATADV_THROUGHPUT_DEFAULT_VALUE;
 	return true;
 }



